@inject Services.WarehouseState Warehouse
@implements IDisposable

<select class="form-select form-select-sm" style="width: auto;"
        @onchange="OnWarehouseSelected">
    @foreach (var wh in Services.WarehouseState.AvailableWarehouses)
    {
        <option value="@wh.Id" selected="@(wh.Id == Warehouse.CurrentWarehouseId)">
            @wh.Name
        </option>
    }
</select>

@code {
    protected override void OnInitialized()
    {
        Warehouse.OnChange += OnStateChanged;
    }

    private void OnWarehouseSelected(ChangeEventArgs e)
    {
        Warehouse.SetWarehouse(e.Value?.ToString() ?? "");
    }

    private void OnStateChanged() => InvokeAsync(StateHasChanged);

    public void Dispose() => Warehouse.OnChange -= OnStateChanged;
}

@inject Services.InventoryAlertService Alerts
@implements IDisposable

@if (Alerts.LowStockCount > 0)
{
    <span class="badge bg-danger rounded-pill">@Alerts.LowStockCount</span>
}
else
{
    <span class="badge bg-success rounded-pill">0</span>
}

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        Alerts.OnChange += _handler;
    }

    public void Dispose()
    {
        if (_handler is not null)
            Alerts.OnChange -= _handler;
    }
}

