@inject Services.InventoryAlertService Alerts
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Site</h5>
        <p class="card-text fs-4">@Warehouse.CurrentWarehouseName (@Warehouse.CurrentWarehouseId)</p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text">
            @if (Alerts.LowStockCount > 0)
            {
                <span class="text-danger fs-3 fw-bold">@Alerts.LowStockCount</span>
                <span class="ms-2">items below minimum level</span>
            }
            else
            {
                <span class="text-success fs-3 fw-bold">0</span>
                <span class="ms-2">all stock levels healthy</span>
            }
        </p>
        <small class="text-muted">Refreshes every 10 seconds</small>
    </div>
</div>

@code {
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        _alertHandler = () => InvokeAsync(StateHasChanged);

        Warehouse.OnChange += _warehouseHandler;
        Alerts.OnChange += _alertHandler;

        Alerts.StartPolling();
    }

    public void Dispose()
    {
        Alerts.StopPolling();

        if (_warehouseHandler is not null)
            Warehouse.OnChange -= _warehouseHandler;
        if (_alertHandler is not null)
            Alerts.OnChange -= _alertHandler;
    }
}

